INSERT INTO scenes (id, user_id, date, version, place, starts_at, ends_at, type, narration, mind, `lines`, created_at)
VALUES (1,1,'2026-03-15','v1','중앙도서관','09:00:00','11:00:00','ACTION','도서관 3층 창가 자리에서 혼자 전공 서적을 펼쳤다. 두 시간 동안 진도는 스무 장 남짓 나갔다.','아 공부하기 싫어. 하지만 해내야지!',NULL,'2026-08-05 17:50:56.296651'),
       (2,1,'2026-03-15','v1','중앙도서관 편의점','11:00:00','11:32:00','ACTION','편의점에서 삼각김밥과 커피로 간단히 끼니를 때웠다.',NULL,NULL,'2026-08-05 17:50:56.296654'),
       (3,1,'2026-03-15','v1','도서관 앞 벤치','11:40:00','12:30:00','DIALOGUE',NULL,NULL,'[{\"t\": \"narr\", \"text\": \"잠깐 바람 쐬러 나왔더니 지민이 먼저 벤치에 앉아 있었다.\"}, {\"t\": \"bubble\", \"text\": \"오 서연아, 오늘도 도서관 붙박이야?\", \"action\": \"손을 흔들며\", \"userId\": 3}, {\"t\": \"bubble\", \"text\": \"붙박이는 무슨. 오후엔 약속 있어서 나가야 돼.\", \"action\": \"옆에 앉으며\", \"userId\": 1}, {\"t\": \"bubble\", \"text\": \"약속? 혹시 상준이야?\", \"action\": \"눈을 반짝이며\", \"userId\": 3}, {\"t\": \"narr\", \"text\": \"지민이 장난스럽게 웃자 괜히 말문이 막혔다.\"}, {\"t\": \"bubble\", \"text\": \"그냥 영화 보기로 한 거야. 별거 아니야.\", \"action\": \"커피를 만지작거리며\", \"userId\": 1}]','2026-08-05 17:50:56.299553'),
       (4,1,'2026-03-15','v1','지하철 2호선','13:20:00','13:55:00','ACTION','약속 시간보다 조금 일찍 나섰다. 창밖으로 지나가는 풍경을 보며 아무 노래나 재생했다.','괜히 옷을 세 번이나 갈아입었네.',NULL,'2026-08-05 17:50:56.299572'),
       (5,1,'2026-03-15','v1','영화관 로비','14:00:00','14:20:00','DIALOGUE',NULL,NULL,'[{\"t\": \"narr\", \"text\": \"서연과 상준은 표를 끊은 후 영화 시간을 기다리며 대화를 나눴다.\"}, {\"t\": \"bubble\", \"text\": \"이 영화 평 좋더라\", \"action\": \"웃으며\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"그래? 기대된다\", \"action\": \"끄덕이며\", \"userId\": 1}, {\"t\": \"narr\", \"text\": \"팝콘 번호표가 울려 상준이 팝콘을 가지러 갔다 왔다.\"}, {\"t\": \"bubble\", \"text\": \"반반으로 시켰어. 너 단짠 좋아하잖아\", \"action\": \"팝콘을 건네며\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"기억하고 있었네\", \"action\": \"받아 들며\", \"userId\": 1}, {\"t\": \"bubble\", \"text\": \"영화 시간 다 됐다, 들어가자\", \"action\": \"일어서며\", \"userId\": 2}, {\"t\": \"narr\", \"text\": \"둘은 영화를 보러 들어갔다.\"}]','2026-08-05 17:50:56.299830'),
       (6,1,'2026-03-15','v1','상영관','14:20:00','16:20:00','ACTION','둘은 나란히 앉아 영화를 봤다. 중간에 상준이 웃음을 참지 못해 어깨를 들썩였다.','영화보다 옆자리가 더 신경 쓰인다.',NULL,'2026-08-05 17:50:56.299832'),
       (7,1,'2026-03-15','v1','영화관 근처 카페','16:35:00','17:30:00','DIALOGUE',NULL,NULL,'[{\"t\": \"narr\", \"text\": \"영화가 끝나고 자연스럽게 근처 카페로 자리를 옮겼다.\"}, {\"t\": \"bubble\", \"text\": \"결말 어떻게 생각해? 난 좀 아쉬웠는데\", \"action\": \"컵을 내려놓으며\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"난 오히려 그게 현실적이라 좋았어\", \"action\": \"잠시 생각하다가\", \"userId\": 1}, {\"t\": \"narr\", \"text\": \"취향이 갈렸지만 대화는 끊기지 않고 한참 이어졌다.\"}, {\"t\": \"bubble\", \"text\": \"다음 주 토요일에도 시간 돼?\", \"action\": \"조심스럽게\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"음... 생각해보고 알려줄게\", \"action\": \"웃으며\", \"userId\": 1}]','2026-08-05 17:50:56.299866'),
       (8,1,'2026-03-15','v1','자취방','22:10:00','22:45:00','ACTION','씻고 나와 침대에 누워 오늘 찍은 사진을 한 장씩 넘겨봤다.','생각보다 편했다. 다음에 또 봐도 괜찮을 것 같은데.',NULL,'2026-08-05 17:50:56.299867'),
       (9,2,'2026-03-15','v1','동네 헬스장','10:20:00','11:10:00','ACTION','평소보다 이른 시간에 헬스장에 갔다. 러닝머신 위에서 계속 시계를 확인했다.','괜히 오늘따라 몸이 안 풀리네.',NULL,'2026-08-05 17:50:56.461104'),
       (10,2,'2026-03-15','v1','자취방','11:40:00','12:50:00','ACTION','옷장을 열어놓고 한참을 서 있었다. 결국 제일 무난한 셔츠를 골랐다.','너무 신경 쓴 티 나면 안 되는데.',NULL,'2026-08-05 17:50:56.461106'),
       (11,2,'2026-03-15','v1','시내버스','13:30:00','13:55:00','ACTION','버스 뒷자리에 앉아 영화 예매 내역을 몇 번이나 다시 확인했다.',NULL,NULL,'2026-08-05 17:50:56.461106'),
       (12,2,'2026-03-15','v1','영화관 로비','14:00:00','14:20:00','DIALOGUE',NULL,NULL,'[{\"t\": \"narr\", \"text\": \"서연과 상준은 표를 끊은 후 영화 시간을 기다리며 대화를 나눴다.\"}, {\"t\": \"bubble\", \"text\": \"이 영화 평 좋더라\", \"action\": \"웃으며\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"그래? 기대된다\", \"action\": \"끄덕이며\", \"userId\": 1}, {\"t\": \"narr\", \"text\": \"팝콘 번호표가 울려 상준이 팝콘을 가지러 갔다 왔다.\"}, {\"t\": \"bubble\", \"text\": \"반반으로 시켰어. 너 단짠 좋아하잖아\", \"action\": \"팝콘을 건네며\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"기억하고 있었네\", \"action\": \"받아 들며\", \"userId\": 1}, {\"t\": \"bubble\", \"text\": \"영화 시간 다 됐다, 들어가자\", \"action\": \"일어서며\", \"userId\": 2}, {\"t\": \"narr\", \"text\": \"둘은 영화를 보러 들어갔다.\"}]','2026-08-05 17:50:56.461208'),
       (13,2,'2026-03-15','v1','상영관','14:20:00','16:20:00','ACTION','웃긴 장면에서 참지 못하고 어깨를 들썩였다. 옆자리에서도 작게 웃는 소리가 들렸다.','같이 웃는 타이밍이 맞는 사람이구나.',NULL,'2026-08-05 17:50:56.461210'),
       (14,2,'2026-03-15','v1','영화관 근처 카페','16:35:00','17:30:00','DIALOGUE',NULL,NULL,'[{\"t\": \"narr\", \"text\": \"영화가 끝나고 자연스럽게 근처 카페로 자리를 옮겼다.\"}, {\"t\": \"bubble\", \"text\": \"결말 어떻게 생각해? 난 좀 아쉬웠는데\", \"action\": \"컵을 내려놓으며\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"난 오히려 그게 현실적이라 좋았어\", \"action\": \"잠시 생각하다가\", \"userId\": 1}, {\"t\": \"narr\", \"text\": \"취향이 갈렸지만 대화는 끊기지 않고 한참 이어졌다.\"}, {\"t\": \"bubble\", \"text\": \"다음 주 토요일에도 시간 돼?\", \"action\": \"조심스럽게\", \"userId\": 2}, {\"t\": \"bubble\", \"text\": \"음... 생각해보고 알려줄게\", \"action\": \"웃으며\", \"userId\": 1}]','2026-08-05 17:50:56.461255'),
       (15,2,'2026-03-15','v1','영화관 앞 버스정류장','17:40:00','18:10:00','ACTION','버스가 올 때까지 같이 서 있었다. 서연이 탄 버스가 사라질 때까지 자리를 뜨지 않았다.','생각해본다는 게 거절은 아니겠지.',NULL,'2026-08-05 17:50:56.461256'),
       (16,2,'2026-03-15','v1','자취방','23:00:00','23:30:00','ACTION','침대에 누워 휴대폰을 켰다 껐다 했다. 결국 아무 메시지도 보내지 못했다.','내일 아침에 보내는 게 낫겠다.',NULL,'2026-08-05 17:50:56.461258'),
       (17,3,'2026-03-15','v1','학과 사무실','09:30:00','11:20:00','ACTION','근로 장학생 업무로 오전 내내 서류를 정리했다. 복사기가 두 번이나 걸렸다.','이 복사기 진짜 언제 바꿔주지.',NULL,'2026-08-05 17:50:56.503435'),
       (18,3,'2026-03-15','v1','도서관 앞 벤치','11:40:00','12:30:00','DIALOGUE',NULL,NULL,'[{\"t\": \"narr\", \"text\": \"잠깐 바람 쐬러 나왔더니 지민이 먼저 벤치에 앉아 있었다.\"}, {\"t\": \"bubble\", \"text\": \"오 서연아, 오늘도 도서관 붙박이야?\", \"action\": \"손을 흔들며\", \"userId\": 3}, {\"t\": \"bubble\", \"text\": \"붙박이는 무슨. 오후엔 약속 있어서 나가야 돼.\", \"action\": \"옆에 앉으며\", \"userId\": 1}, {\"t\": \"bubble\", \"text\": \"약속? 혹시 상준이야?\", \"action\": \"눈을 반짝이며\", \"userId\": 3}, {\"t\": \"narr\", \"text\": \"지민이 장난스럽게 웃자 괜히 말문이 막혔다.\"}, {\"t\": \"bubble\", \"text\": \"그냥 영화 보기로 한 거야. 별거 아니야.\", \"action\": \"커피를 만지작거리며\", \"userId\": 1}]','2026-08-05 17:50:56.503526'),
       (19,3,'2026-03-15','v1','학생식당','12:40:00','13:20:00','ACTION','혼자 늦은 점심을 먹으며 아까 서연의 표정을 떠올렸다.','별거 아니라면서 왜 귀가 빨개져.',NULL,'2026-08-05 17:50:56.503528'),
       (20,3,'2026-03-15','v1','학교 앞 스터디카페','15:00:00','17:10:00','ACTION','다음 주 발표 자료를 만들었다. 슬라이드 열두 장 중 다섯 장에서 멈췄다.',NULL,NULL,'2026-08-05 17:50:56.503529'),
       (21,3,'2026-03-15','v1','자취방','19:00:00','19:40:00','ACTION','저녁을 시켜 먹으며 메신저 창을 열었다. \'어땠어?\'까지 쓰다가 지웠다.','먼저 말할 때까지 기다려주는 게 낫겠지.',NULL,'2026-08-05 17:50:56.503529'),
       (22,3,'2026-03-15','v1','자취방','22:20:00','22:50:00','ACTION','불을 끄고 누웠는데 잠이 오지 않아 한참 천장을 봤다.','내일은 내 발표나 신경 쓰자.',NULL,'2026-08-05 17:50:56.503530');

