INSERT INTO questions (id, user_id, date, version, time, type, text, options, choice, answered_at, is_skipped, created_at)
VALUES (1,1,'2026-03-15','v1','12:35:00','PERSONA','지민이 \'오늘 약속 상준이냐\'고 물었을 때, 당신의 에이전트는 \'별거 아니다\'라고 넘겼어요. 실제로는 어떠세요?','[\"맞아, 굳이 말하고 싶지 않았어\", \"그냥 정말 별일 아니야\"]',NULL,NULL,0,'2026-08-05 17:50:56.333864'),
       (2,1,'2026-03-15','v1','14:10:00','PROMISE','상준이 다음 주 토요일 데이트를 신청했고, 당신의 에이전트는 수락했어요. 어떻게 할까요?','[\"그대로 수락한다\", \"취소한다\"]',NULL,NULL,0,'2026-08-05 17:50:56.333865'),
       (3,1,'2026-03-15','v1','14:15:00','PERSONA','상준이 \'산이 좋아 바다가 좋아?\' 하고 물었고, 당신의 에이전트는 \'바다\'라고 답했어요. 실제로는 어떠세요?','[\"산\", \"바다\"]',NULL,NULL,0,'2026-08-05 17:50:56.333865'),
       (4,1,'2026-03-15','v1','17:35:00','PROMISE','지민이 다음 주에 셋이 같이 보자고 제안했어요. 상준에게도 물어볼까요?','[\"같이 보자고 한다\", \"둘이서만 본다\", \"다음에 이야기한다\"]',NULL,NULL,0,'2026-08-05 17:50:56.333865'),
       (5,2,'2026-03-15','v1','14:12:00','PROMISE','당신의 에이전트가 서연에게 다음 주 토요일 데이트를 신청했어요. 그대로 진행할까요?','[\"그대로 진행한다\", \"없던 일로 한다\"]',NULL,NULL,0,'2026-08-05 17:50:56.470559'),
       (6,2,'2026-03-15','v1','16:50:00','PERSONA','영화 결말에 대해 당신의 에이전트는 \'아쉬웠다\'고 답했어요. 실제로는 어떠세요?','[\"아쉬웠다\", \"만족스러웠다\", \"별생각 없었다\"]',NULL,NULL,0,'2026-08-05 17:50:56.470560'),
       (7,2,'2026-03-15','v1','18:20:00','PROMISE','다음 주 토요일에 만난다면 어디가 좋을까요?','[\"전시회\", \"한강 산책\", \"서연이 정하는 곳\"]',NULL,NULL,0,'2026-08-05 17:50:56.470560'),
       (8,2,'2026-03-15','v1','23:35:00','PERSONA','당신의 에이전트는 마음에 드는 사람에게 먼저 연락하는 편으로 행동했어요. 실제로는 어떠세요?','[\"먼저 연락하는 편\", \"상대가 먼저 하길 기다리는 편\"]',NULL,NULL,0,'2026-08-05 17:50:56.470560'),
       (9,3,'2026-03-15','v1','12:35:00','PROMISE','당신의 에이전트가 서연에게 다음 주에 셋이 함께 보자고 제안했어요. 어떻게 할까요?','[\"그대로 제안한다\", \"둘이 편하게 보라고 한다\"]',NULL,NULL,0,'2026-08-05 17:50:56.509715'),
       (10,3,'2026-03-15','v1','13:25:00','PERSONA','친구가 말을 아낄 때 당신의 에이전트는 더 캐묻지 않고 넘어갔어요. 실제로는 어떠세요?','[\"기다려주는 편\", \"궁금하면 물어보는 편\", \"상대에 따라 다름\"]',NULL,NULL,0,'2026-08-05 17:50:56.509715'),
       (11,3,'2026-03-15','v1','19:45:00','PERSONA','당신의 에이전트는 먼저 연락하려다 결국 보내지 않았어요. 실제로는 어떠세요?','[\"그냥 보냈을 것 같다\", \"나도 안 보냈을 것 같다\"]',NULL,NULL,0,'2026-08-05 17:50:56.509715');

