INSERT INTO relationships (id, user_id, date, version, partner_user_id, intimacy, partner_model, update_time, created_at)
VALUES (1,1,'2026-03-15','v1',2,42,'발표할 때 막힘없이 또박또박 말하고, 처음 본 사람한테도 먼저 말을 거는 외향적인 사람. 농담을 잘 받아주고 은근히 챙겨주는 다정함이 있다. 다만 약속에 종종 늦어서 무심한가 싶을 때도 있었다. 영화·음악 취향이 나랑 잘 맞아서 같이 있으면 대화가 끊기지 않는다.','17:30:00','2026-08-05 17:50:56.365178'),
       (2,1,'2026-03-15','v1',3,71,'1학년 때부터 알고 지낸 학과 동기. 눈치가 빨라서 표정만 봐도 무슨 일 있는지 먼저 물어본다. 짓궂게 놀리다가도 정작 중요한 순간엔 진지하게 들어준다. 비밀을 맡겨도 되는 몇 안 되는 사람.','12:30:00','2026-08-05 17:50:56.365179'),
       (3,2,'2026-03-15','v1',1,42,'말수가 많지는 않은데 한마디 한마디가 생각을 거쳐 나오는 느낌이다. 리액션이 크지 않아 처음엔 재미없어하나 싶었는데, 알고 보니 관심 있는 주제엔 눈이 반짝인다. 약속 시간보다 늘 먼저 나와 있어서 괜히 미안해진다. 취향이 나랑 다른데도 그 다름을 설명해주는 게 좋다.','18:10:00','2026-08-05 17:50:56.476979'),
       (4,3,'2026-03-15','v1',1,71,'1학년 때부터 봐온 동기. 겉으로는 무덤덤해 보여도 속으로 훨씬 많이 생각하는 애다. 자기 얘기를 잘 안 하는 편이라 물어봐 줘야 하나 싶다가도, 캐물으면 오히려 닫히는 걸 알아서 그냥 옆에 있어 주는 쪽을 택하게 된다. 부탁하면 절대 거절 안 하는 게 늘 마음에 걸린다.','12:30:00','2026-08-05 17:50:56.513977');

